const fs = require('fs');
const path = require('path');
const vm = require('vm');

function validateRule(ruleContent) {
  const issues = [];
  const warnings = [];
  const passes = [];

  let rule = null;
  if (typeof ruleContent === 'string') {
    try {
      rule = JSON.parse(ruleContent);
    } catch (e) {
