      passes.push('二级详情页包含剧名上下文保护卡片');
    }
  }

  // 5. 防盗链注解检测
  const fullRuleStr = JSON.stringify(rule);
  if (!fullRuleStr.includes('@Referer=') && !fullRuleStr.includes(';{Referer@')) {
