  } else {
    passes.push('包含标准防盗链注解 (@Referer= / ;{Referer@...})');
  }

  return {
    valid: issues.length === 0,
    issues,
    warnings,
    passes,
  };
}

// 命令行执行支持
if (require.main === module) {
