  if (result.issues.length > 0) {
    console.log('\n【阻断缺陷】:');
    result.issues.forEach(i => console.log('  ✗ ' + i));
  }
  console.log('===============================================================\n');

  process.exit(result.valid ? 0 : 1);
}

module.exports = { validateRule };
