          } catch (cascadeErr) {
            console.error('❌ 三级级联规则仿真执行失败:', cascadeErr.message);
          }
        }
      }
    } catch (err) {
      console.error('❌ detail_find_rule 执行抛错:', err.message);
    }
  }

  console.log('\n=================================================================\n');
}

if (require.main === module) {
